using DomainModel.ViewModels.SiteSetting; namespace DataAccess.Repositories.SiteSetting; public static class SiteSettingMapper { public static void MapForUpdate(SiteSettingEditModel m,DomainModel.Models.SiteSetting e){e.SiteName=m.SiteName.Trim();e.SiteDescription=m.SiteDescription;e.LogoPath=m.LogoPath??e.LogoPath;e.FaviconPath=m.FaviconPath??e.FaviconPath;e.FooterText=m.FooterText;e.InstagramUrl=m.InstagramUrl;e.TelegramUrl=m.TelegramUrl;e.LinkedInUrl=m.LinkedInUrl;e.DefaultSeoTitle=m.DefaultSeoTitle;e.DefaultSeoDescription=m.DefaultSeoDescription;e.DefaultSeoKeywords=m.DefaultSeoKeywords;e.IsSiteActive=m.IsSiteActive;} }
